#nullable enable // autogenerated

using MVZ2.Level.Inputing;
using MVZ2.Level.UI;
using MVZ2.Options;
using MVZ2Logic;
using MVZ2Logic.Audios;
using MVZ2Logic.Games;
using MVZ2Logic.HeldItems;
using MVZ2Logic.Inputs;
using MVZ2Logic.Level;
using MVZ2Logic.Options;
using PVZEngine;
using PVZEngine.Level;
using UnityEngine;
using UnityEngine.EventSystems;
using static MVZ2.Level.UI.LevelUIPreset;

namespace MVZ2.Level
{
    public partial class LevelController
    {
        private void Awake_UI()
        {
            ui.OnExitLevelToNoteCalled += OnUIExitLevelToNoteCalledCallback;
            ui.OnStartGameCalled += StartGame;
            ui.SetMobile(Main.UseMobileLayout());

            var uiPreset = GetUIPreset();
            uiPreset.OnRaycastReceiverPointerInteraction += UI_OnRaycastReceiverPointerInteractionCallback;
            uiPreset.OnMenuButtonClick += UI_OnMenuButtonClickCallback;
            uiPreset.OnSpeedUpButtonClick += UI_OnSpeedUpButtonClickCallback;

            uiPreset.HideMoney();
            SetUIVisibleState(VisibleState.Nothing);
        }
        private void InitLevelEngine_UI(LevelEngine level)
        {
            levelRaycaster.Init(level);
        }
        private void StartGame_UI()
        {
            // 设置UI可见状态
            SetUIVisibleState(VisibleState.InLevel);
            RefreshUIAtLevelStart();

            var uiPreset = GetUIPreset();
            uiPreset.SetReceiveRaycasts(true);
            uiPreset.UpdateFrame(0);
        }
        private void WriteToSerializable_UI(SerializableLevelController seri)
        {
            seri.uiPreset = GetUIPreset().ToSerializable();
        }
        private void ReadFromSerializable_UI(SerializableLevelController seri)
        {
            // uiPreset的animator.Update会导致第一次加载该场景时，蓝图UI的子模型显示状态不正确，所以放在前面
            var uiPreset = GetUIPreset();
            if (seri.uiPreset != null)
                uiPreset.LoadFromSerializable(seri.uiPreset);
            uiPreset.UpdateFrame(0);
        }
        public ILevelUI GetUI()
        {
            return ui;
        }
        public LevelUIPreset GetUIPreset()
        {
            return ui.GetUIPreset();
        }
        private void RefreshUIAtLevelInit()
        {
            var uiPreset = GetUIPreset();
            uiPreset.UpdateFrame(0);
            SetStarshardIcon();
            UpdateHotkeyTexts();
        }
        private void RefreshUIAtLevelStart()
        {
            // 关卡名
            UpdateLevelName();
            // 能量、关卡进度条、手持物品、蓝图状态、星之碎片
            UpdateInLevelUI(0);
            // 金钱
            UpdateMoney();
            // 难度名称
            UpdateDifficultyName();
            // 诅咒数量
            UpdateCurseIcon();
            // 关卡进度条
            RefreshProgressBar();
        }

        #region 金钱
        public void ShowMoney()
        {
            var levelUI = GetUIPreset();
            levelUI.ResetMoneyFadeTime();
        }
        public void SetMoneyFade(bool fade)
        {
            var levelUI = GetUIPreset();
            levelUI.SetMoneyFade(fade);
        }
        private void UpdateMoney()
        {
            var ui = GetUIPreset();
            int displayedMoney = level.GetMoney() - level.GetDelayedMoney();
            if (cachedDisplayedMoney != displayedMoney)
            {
                cachedDisplayedMoney = displayedMoney;
                ui.SetMoney(displayedMoney.ToString("N0"));
            }
        }
        #endregion

        #region 关卡名
        public void UpdateLevelName()
        {
            var levelUI = GetUIPreset();
            levelUI.SetLevelName(LevelManager.GetStageName(level));
        }
        #endregion

        #region 难度
        private void UpdateDifficultyName()
        {
            var difficultyName = Game.GetDifficultyName(level.Difficulty);
            var levelUI = GetUIPreset();
            levelUI.SetDifficulty(difficultyName);
        }
        #endregion

        #region 难度
        private void UpdateCurseIcon()
        {
            var levelUI = GetUIPreset();
            var curseCount = level.GetCurseCount();
            levelUI.SetCurseIconActive(curseCount > 0 && IsGameStarted());
            levelUI.SetCurseIconText(curseCount.ToString());
        }
        #endregion

        #region 提示红字
        private void PlayReadySetBuild()
        {
            var ui = GetUIPreset();
            ui.ShowReadySetBuild();
            level.PlaySound(LogicSoundID.readySetBuild);
        }
        #endregion

        #region 能量
        public void FlickerEnergy()
        {
            var levelUI = GetUIPreset();
            levelUI.FlickerEnergy();
        }
        private void UpdateEnergy()
        {
            var ui = GetUIPreset();
            int energy = Mathf.FloorToInt(Mathf.Max(0, level.Energy - level.GetDelayedEnergy()));
            if (energy != cachedDisplayedEnergy)
            {
                cachedDisplayedEnergy = energy;
                ui.SetEnergy($"{energy}");
            }
        }
        #endregion

        #region UI可见度
        private void SetUIVisibleState(VisibleState state)
        {
            var levelUI = GetUIPreset();
            levelUI.SetUIVisibleState(state);
        }
        #endregion

        #region 热键
        public void UpdateHotkeyTexts()
        {
            var preset = ui.GetUIPreset();
            preset.SetPickaxeHotkeyText(GetHotkeyName(HotKeys.pickaxe));
            preset.SetStarshardHotkeyText(GetHotkeyName(HotKeys.starshard));
            preset.SetTriggerHotkeyText(GetHotkeyName(HotKeys.trigger));
            preset.SetSpeedUpHotkeyText(GetHotkeyName(HotKeys.fastForward));
            blueprintController.ForceUpdateBlueprintHotkeyTexts();
        }
        private string GetHotkeyName(NamespaceID keyID)
        {
            if (Global.Game.IsMobile() || !Main.OptionsManager.ShowHotkeyIndicators())
                return string.Empty;
            var keycode = Main.OptionsManager.GetKeyBinding(keyID);
            return keycode != KeyCode.None ? Main.InputManager.GetKeyCodeName(keycode) : string.Empty;
        }
        #endregion

        public void SetUIAndInputDisabled(bool disabled)
        {
            inputAndUIDisabled = disabled;
            ui.SetUIDisabled(disabled);
        }
        /// <summary>
        /// 更新能量、关卡进度条、手持物品、蓝图状态、星之碎片。
        /// </summary>
        private void UpdateInLevelUI(float deltaTime)
        {
            var ui = GetUIPreset();
            UpdateEnergy();
            UpdateLevelProgressUI();
            UpdateHeldSlotUI();
            UpdateStarshardsUIRealtime();
        }

        #region 事件回调
        private void UI_OnRaycastReceiverPointerInteractionCallback(LawnArea area, PointerEventData eventData, PointerInteraction interaction)
        {
            if (!IsGameRunning())
                return;
            var target = new HeldItemTargetLawn(level, area);
            var pointerParams = InputHelper.GetPointerInteractionParamsFromEventData(eventData, interaction);
            level.DoHeldItemPointerEvent(target, pointerParams);

            switch (interaction)
            {
                case PointerInteraction.Enter:
                    OnRaycastReceiverPointerEnter(area, eventData);
                    break;
                case PointerInteraction.Exit:
                    OnRaycastReceiverPointerExit(area, eventData);
                    break;
            }
        }
        private void OnRaycastReceiverPointerEnter(LawnArea area, PointerEventData eventData)
        {
            isPointingLawnArea = true;
            pointingLawnArea = area;
            pointingLawnPointerId = eventData.pointerId;
            UpdateHeldHighlight();
        }
        private void OnRaycastReceiverPointerExit(LawnArea area, PointerEventData eventData)
        {
            isPointingLawnArea = false;
            pointingLawnPointerId = -1;
            UpdateHeldHighlight();
        }
        private void UI_OnMenuButtonClickCallback()
        {
            if (IsGameRunning())
            {
                if (!IsPauseDisabled())
                {
                    PauseGame();
                    level.PlaySound(LogicSoundID.pause);
                    ShowOptionsDialog();
                }
            }
            else
            {
                ShowOptionsDialog();
            }
        }
        private void UI_OnOptionsMenuCloseCallback(bool needsReload)
        {
            if (!IsGameStarted())
            {
                ui.SetOptionsDialogActive(false);
            }
            else
            {
                ResumeGameDelayed(100);
            }
        }
        private void UI_OnSpeedUpButtonClickCallback()
        {
            SwitchSpeedUp();
        }
        private void UI_OnBlueprintPointerInteractionCallback(int index, PointerEventData eventData, PointerInteraction interaction, bool conveyor)
        {
            if (!IsGameRunning())
                return;
            var target = new HeldItemTargetBlueprint(level, index, conveyor);
            var pointerParams = InputHelper.GetPointerInteractionParamsFromEventData(eventData, interaction);
            level.DoHeldItemPointerEvent(target, pointerParams);

            switch (interaction)
            {
                case PointerInteraction.Enter:
                    OnBlueprintPointerEnter(index, eventData, conveyor);
                    break;
                case PointerInteraction.Exit:
                    OnBlueprintPointerExit(index, eventData, conveyor);
                    break;
            }
        }
        private void OnBlueprintPointerEnter(int index, PointerEventData eventData, bool conveyor)
        {
            pointingBlueprint = index;
            pointingBlueprintPointerId = eventData.pointerId;
            pointingBlueprintConveyor = conveyor;
            UpdateHeldHighlight();
        }
        private void OnBlueprintPointerExit(int index, PointerEventData eventData, bool conveyor)
        {
            pointingBlueprint = -1;
            pointingBlueprintPointerId = -1;
            pointingBlueprintConveyor = conveyor;
            UpdateHeldHighlight();
        }

        #endregion

        #region 属性字段
        private bool inputAndUIDisabled;
        private bool isPointingLawnArea;
        private LawnArea pointingLawnArea;
        private int pointingLawnPointerId;
        private int pointingBlueprint;
        private int pointingBlueprintPointerId;
        private bool pointingBlueprintConveyor;
        private int cachedDisplayedMoney = -1;
        private int cachedDisplayedEnergy = -1;

        [Header("UI")]
        [SerializeField]
        private LevelUI ui = null!;
        [SerializeField]
        private LevelRaycaster levelRaycaster = null!;
        #endregion
    }
}
